_UNI_RANGES = [(3712, 3839), (11904, 12255), (12288, 12543), (12592, 12687), (12800, 13311), (19968, 20063), (24417, 24417), (42560, 42655), (43520, 43743), (65280, 65519)]

EMBEDDED = [  # অগ্রাধিকার ক্রমে: (নাম, বাইট-লোডার, কোডপয়েন্ট রেঞ্জ)
    ("dejavu", _DEJAVU_B64, _DEJAVU_RANGES),
    ("serif", _SERIF_B64, _SERIF_RANGES),
    ("uni", _UNI_B64, _UNI_RANGES),
]

def font_bytes(name):
    for n, b64, _ in EMBEDDED:
        if n == name:
            return zlib.decompress(base64.b64decode(b64))
    raise KeyError(name)

def covers(name, cp):
    for n, _, rg in EMBEDDED:
        if n == name:
            return any(a <= cp <= b for a, b in rg)
    return False
